parameters.jsCode:
// Extrai o JSON gerado pelo Gemini e prepara o payload para o site
const rawOutput = $input.first().json.text || $input.first().json.output || JSON.stringify($input.first().json);
let cleanJson = {};
try {
  const sanitized = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
  cleanJson = JSON.parse(sanitized);
} catch (e) {
  cleanJson = {
    title: $node["Webhook Receber Oferta Shopee"].json.body.title || 'Achadinho Shopee',
    description: 'Confira esse super achadinho para sua casa.',
    category: 'Casa Inteligente',
    price_original: $node["Webhook Receber Oferta Shopee"].json.body.price_original || null,
    price_promo: $node["Webhook Receber Oferta Shopee"].json.body.price_promo || 29.90,
    discount_percent: 40,
    image_url: $node["Webhook Receber Oferta Shopee"].json.body.image_url || '',
    affiliate_url: $node["Webhook Receber Oferta Shopee"].json.body.affiliate_url,
    shopee_item_id: $node["Webhook Receber Oferta Shopee"].json.body.shopee_item_id || null
  };
}

return [{ json: cleanJson }];
